import { Platform } from 'react-native';
import { File, Paths } from 'expo-file-system';
import { createAudioPlayer } from 'expo-audio';
import { synthesizeLoop } from './synth';
import type { Phase } from '../types/character';

/**
 * Plays a character's synthesized performance loop.
 *
 * The loop itself is generated by the pure-TS synth (no audio assets); this
 * module only handles playback per platform:
 *   - web: decode the WAV bytes with the Web Audio API and loop them.
 *   - native: write the WAV to the app cache and loop it with expo-audio.
 */

export interface PerformAudioHandle {
  stop: () => Promise<void>;
}

const BASE64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Minimal base64 encoder (Hermes-safe, no btoa dependency). */
export function toBase64(bytes: Uint8Array): string {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i];
    const b = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const c = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const triple = (a << 16) | (b << 8) | c;
    out += BASE64_CHARS[(triple >> 18) & 63];
    out += BASE64_CHARS[(triple >> 12) & 63];
    out += i + 1 < bytes.length ? BASE64_CHARS[(triple >> 6) & 63] : '=';
    out += i + 2 < bytes.length ? BASE64_CHARS[triple & 63] : '=';
  }
  return out;
}

async function startWebAudio(wav: Uint8Array): Promise<PerformAudioHandle> {
  const w = window as unknown as {
    AudioContext?: typeof AudioContext;
    webkitAudioContext?: typeof AudioContext;
  };
  const Ctor = w.AudioContext ?? w.webkitAudioContext;
  if (!Ctor) throw new Error('Web Audio is not available in this browser');
  const ctx = new Ctor();
  try {
    await ctx.resume();
  } catch {
    // resume is best-effort; playback attempt continues
  }
  const bytes = wav.slice(); // copy: decodeAudioData detaches the buffer
  const audioBuf = await ctx.decodeAudioData(bytes.buffer as ArrayBuffer);
  const src = ctx.createBufferSource();
  src.buffer = audioBuf;
  src.loop = true;
  src.connect(ctx.destination);
  src.start();
  return {
    stop: async (): Promise<void> => {
      try {
        src.stop();
      } catch {
        // already stopped
      }
      try {
        await ctx.close();
      } catch {
        // already closed
      }
    },
  };
}

async function startNativeAudio(
  wav: Uint8Array,
  characterId: number,
  phase: Phase,
): Promise<PerformAudioHandle> {
  const file = new File(Paths.cache, `sprunki-loop-${characterId}-${phase}.wav`);
  const writer = file.writableStream().getWriter();
  await writer.write(wav);
  await writer.close();
  const player = createAudioPlayer(file.uri);
  player.loop = true;
  player.play();
  return {
    stop: async (): Promise<void> => {
      try {
        player.pause();
      } catch {
        // already paused
      }
      player.remove();
    },
  };
}

/** Start looping the character's song. Caller must call stop() when done. */
export async function startPerformAudio(
  characterId: number,
  phase: Phase,
): Promise<PerformAudioHandle> {
  const wav = synthesizeLoop(characterId, phase);
  if (Platform.OS === 'web') return startWebAudio(wav);
  return startNativeAudio(wav, characterId, phase);
}
